-- FEEC 100 Cims catalog, personal ascents and private photo storage.
create table public.summits (
  id text primary key,
  name text not null,
  height integer not null check (height > 0),
  region text not null,
  essential boolean not null default false,
  url text not null unique
);
alter table public.summits enable row level security;
grant select on public.summits to anon, authenticated;
create policy "Anyone can read the FEEC catalog" on public.summits for select to anon, authenticated using (true);

create table public.ascent_records (
  user_id uuid not null references auth.users(id) on delete cascade,
  summit_id text not null references public.summits(id) on delete cascade,
  completed_at date not null,
  photo_path text unique,
  created_at timestamptz not null default now(),
  primary key (user_id, summit_id)
);
create index ascent_records_user_completed_idx on public.ascent_records (user_id, completed_at desc);
alter table public.ascent_records enable row level security;
grant select, insert, update, delete on public.ascent_records to authenticated;
create policy "Users can read their own ascents" on public.ascent_records for select to authenticated using ((select auth.uid()) = user_id);
create policy "Users can add their own ascents" on public.ascent_records for insert to authenticated with check ((select auth.uid()) = user_id);
create policy "Users can update their own ascents" on public.ascent_records for update to authenticated using ((select auth.uid()) = user_id) with check ((select auth.uid()) = user_id);
create policy "Users can delete their own ascents" on public.ascent_records for delete to authenticated using ((select auth.uid()) = user_id);

on conflict (id) do update set name=excluded.name,height=excluded.height,region=excluded.region,essential=excluded.essential,url=excluded.url;

values ('summit-photos','summit-photos',false,6291456,array['image/jpeg','image/png','image/webp','image/avif'])
on conflict (id) do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types;
create policy "Users can read their summit photos" on storage.objects for select to authenticated using (bucket_id='summit-photos' and (storage.foldername(name))[1]=(select auth.uid()::text));
create policy "Users can upload their summit photos" on storage.objects for insert to authenticated with check (bucket_id='summit-photos' and (storage.foldername(name))[1]=(select auth.uid()::text));
create policy "Users can replace their summit photos" on storage.objects for update to authenticated using (bucket_id='summit-photos' and (storage.foldername(name))[1]=(select auth.uid()::text)) with check (bucket_id='summit-photos' and (storage.foldername(name))[1]=(select auth.uid()::text));
create policy "Users can delete their summit photos" on storage.objects for delete to authenticated using (bucket_id='summit-photos' and (storage.foldername(name))[1]=(select auth.uid()::text));


